const $=id=>document.getElementById(id),cv=$('board'),g=cv.getContext('2d'),rand=Math.random,TAU=2*Math.PI;
let stock=500,shots=0,hits=0,wins=0,auto=false,held=false,sound=false,ac,lastShot=-1,balls=[],pegs=[],sparks=[],spin=0,queue=0,reels=[7,7,7],flash=0,now=0;
const pockets=[116,300,484],rails=[[33,356,84,423],[567,356,516,423],[45,470,96,515],[555,470,504,515],[173,464,137,515],[427,464,463,515],[239,458,279,515],[361,458,321,515],[196,267,204,239],[204,239,230,224],[230,224,370,224],[370,224,396,239],[396,239,404,267],[196,267,196,340],[404,267,404,340],[196,340,217,359],[217,359,300,375],[300,375,383,359],[383,359,404,340]];
function peg(x,y,r=3.7){pegs.push({x,y,r,light:0})}
for(let row=0;row<10;row++){let y=78+row*43;for(let col=0;col<12;col++){let x=41+col*47+(row%2)*22;if(x>562||((x-300)/285)**2+((y-265)/259)**2>1.07||(x>177&&x<424&&y>208&&y<385))continue;peg(x+Math.sin(col*2+row)*7,y+Math.cos(row+col)*6)}}for(let x of pockets){peg(x-25,493);peg(x+25,493)}
function line(x,y,a,b,color,w){g.beginPath();g.moveTo(x,y);g.lineTo(a,b);g.lineWidth=w;g.strokeStyle=color;g.stroke()}
function circle(x,y,r,c){g.beginPath();g.arc(x,y,r,0,TAU);g.fillStyle=c;g.fill()}
function metal(y,h){let grd=g.createLinearGradient(0,y,0,y+h);[[0,'#f1d3a0'],[.17,'#926a3d'],[.38,'#3d291d'],[.68,'#aa8553'],[1,'#553822']].forEach(([v,c])=>grd.addColorStop(v,c));return grd}
function box(x,y,w,h,r,c,stroke){g.beginPath();g.roundRect(x,y,w,h,r);g.fillStyle=c;g.fill();if(stroke){g.strokeStyle=stroke;g.lineWidth=2;g.stroke()}}
function txt(t,x,y,font,c){g.textAlign='center';g.font=font;g.fillStyle=c;g.fillText(t,x,y)}
function draw(){let d=Math.min(2,devicePixelRatio||1),size=Math.max(1,Math.round(cv.clientWidth*d));if(cv.width!==size){cv.width=cv.height=size}g.setTransform(size/600,0,0,size/600,0,0);g.clearRect(0,0,600,600);
let sh=g.createRadialGradient(300,260,170,300,280,390);sh.addColorStop(0,'#0c080800');sh.addColorStop(1,'#120c09c9');g.fillStyle=sh;g.fillRect(0,0,600,600);
for(let [x,y,a,b] of rails.slice(0,8)){line(x,y+3,a,b+3,'#120d0b',8);line(x,y,a,b,'#82603d',6);line(x,y-1,a,b-1,'#dfbf87',1.6)}
// Precision brass bezel, inset enamel and mechanical number drums.
g.save();g.translate(300,297);let bezel=[[-108,-53],[-83,-72],[83,-72],[108,-53],[108,43],[84,62],[0,78],[-84,62],[-108,43]];g.beginPath();bezel.forEach(([x,y],i)=>i?g.lineTo(x,y):g.moveTo(x,y));g.closePath();g.fillStyle=metal(-72,150);g.fill();g.strokeStyle='#291a12';g.lineWidth=4;g.stroke();box(-97,-51,194,104,11,'#2a1714','#d2ad72');txt('◆   G I N K Y O   ◆',0,-34,'bold 10px Georgia','#e4bf84');box(-86,-26,172,63,4,'#100e0d','#806241');for(let j=0;j<3;j++){let x=-80+j*55;let gr=g.createLinearGradient(0,-23,0,33);gr.addColorStop(0,'#52271e');gr.addColorStop(.45,'#9d4430');gr.addColorStop(1,'#351a17');box(x,-22,49,54,2,gr,'#92673c');g.save();g.shadowColor='#220c08';g.shadowOffsetY=3;txt(spin>0&&spin>(2-j)*.22?String((Math.floor(now*18)+j*3)%9+1):reels[j],x+24,24,'bold italic 51px Georgia','#ffdda2');g.restore();line(x+2,4,x+47,4,'#1e0d0736',1)}
txt('•   J A C K P O T   •',0,47,'9px Georgia','#d9ae75');for(let i=0;i<9;i++)circle(-72+i*18,58-Math.abs(i-4)*1.8,2.3,spin||i%2?'#f5c183':'#9c7046');g.restore();
for(let p of pegs){circle(p.x+1.5,p.y+2.5,p.r+1,'#120e0bc4');circle(p.x,p.y,p.r,p.light?'#ffce80':'#695742');circle(p.x-.6,p.y-.8,p.r*.75,'#cfbaa0');circle(p.x-1.2,p.y-1.6,1.3,'#fff1d2')}
for(let x of pockets){let y=530;box(x-24,y-10,48,16,4,'#1d1410','#b48d5a');line(x-21,y-9,x+21,y-9,'#221d19',4);txt('✦  IN  ✦',x,y+2,'bold 9px Georgia','#f1c98b')}
txt('•    O U T    •',300,583,'bold 11px Georgia','#d4b383');
for(let b of balls){circle(b.x+2,b.y+3,5,'#100e0cb0');let gr=g.createRadialGradient(b.x-1.5,b.y-2,0,b.x,b.y,5.4);gr.addColorStop(0,'#fff');gr.addColorStop(.28,'#f1f4f0');gr.addColorStop(.6,'#8b9694');gr.addColorStop(.85,'#414642');gr.addColorStop(1,'#cfd2c4');circle(b.x,b.y,5,gr)}
for(let p of sparks){g.globalAlpha=Math.min(1,p.t*2);circle(p.x,p.y,1.7,'#ffcb83')}g.globalAlpha=1;if(flash>0){box(207,387,186,31,4,'#321b14ed','#cfa66c');txt('JACKPOT   +100',300,409,'bold 18px Georgia','#ffda91')}}
function status(){for(let [k,v] of Object.entries({stock,shots,hits,wins}))$(k).textContent=v.toLocaleString();$('refill').hidden=stock>0||balls.length>0||spin>0;$('autoplay').setAttribute('aria-checked',String(auto))}
function msg(s){$('log').textContent=s}
function tone(f,d=.05,vol=.045,type='sine'){if(!sound||!ac)return;let o=ac.createOscillator(),a=ac.createGain();o.type=type;o.frequency.value=f;a.gain.setValueAtTime(vol,ac.currentTime);a.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+d);o.connect(a);a.connect(ac.destination);o.start();o.stop(ac.currentTime+d)}
function fire(){if(stock<1||now-lastShot<.15||$('guide').open)return;lastShot=now;stock--;shots++;let pow=+$('power').value;balls.push({x:16,y:533,t:0,launch:true,end:.40+pow*.004+rand()*.035,vx:0,vy:0});tone(170,.08);if(shots===1)msg('발사되었습니다. 금빛 입상구를 노려보세요.');if(!stock)auto=false;status()}
function startSpin(){spin=1.25;reels=Array.from({length:3},()=>1+Math.floor(rand()*9));if(rand()<.12)reels.fill(reels[0])}
function score(x){hits++;stock+=5;msg('입상! 구슬 +5 · 릴 추첨 중');tone(820,.2);for(let i=0;i<16;i++)sparks.push({x,y:516,vx:(rand()-.5)*150,vy:-40-rand()*100,t:.65});if(spin)queue++;else startSpin();status()}
function bounce(b,x,y,r,coef){let dx=b.x-x,dy=b.y-y,dist=Math.hypot(dx,dy);if(dist>=r||!dist)return false;let nx=dx/dist,ny=dy/dist;b.x=x+nx*r;b.y=y+ny*r;let v=b.vx*nx+b.vy*ny;if(v<0){b.vx-=v*(1+coef)*nx;b.vy-=v*(1+coef)*ny;if(Math.abs(nx)<.045)b.vx+=(rand()<.5?-1:1)*15;return true}return false}
function step(dt){now+=dt;if((held||auto)&&now-lastShot>.28)fire();for(let i=balls.length-1;i>=0;i--){let b=balls[i];b.t+=dt;if(b.launch){let t=Math.min(b.t,b.end);if(t<.30){b.x=16;b.y=533-1190*t}else{let u=(t-.30)*2.65;b.x=300-284*Math.cos(u);b.y=176-150*Math.sin(u)}if(b.t>=b.end){let u=(b.end-.30)*2.65;b.launch=false;b.vx=240*Math.sin(u);b.vy=-200*Math.cos(u)}continue}b.vy+=510*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.x<10||b.x>590){b.x=Math.max(10,Math.min(590,b.x));b.vx*=-.66}if(b.y<8){b.y=8;b.vy=Math.abs(b.vy)*.72}
for(let p of pegs){if(bounce(b,p.x,p.y,p.r+5,.56)){p.light=.12;if(Math.abs(b.vy)+Math.abs(b.vx)>60&&rand()<.46)tone(1100+p.x,.035,.014)}}for(let [x,y,a,z] of rails){let dx=a-x,dy=z-y,u=Math.max(0,Math.min(1,((b.x-x)*dx+(b.y-y)*dy)/(dx*dx+dy*dy)));bounce(b,x+u*dx,y+u*dy,7,.48);if(y===224&&z===224&&b.y<224&&Math.abs(b.y-224)<9)b.vx+=(b.x<300?-1:1)*210*dt}
let pocket=pockets.find(x=>Math.abs(b.x-x)<21&&b.y>517&&b.y<540);if(pocket||b.y>610||b.t>23){balls.splice(i,1);if(pocket)score(pocket);status()}}
for(let p of pegs)p.light=Math.max(0,p.light-dt);for(let p of sparks){p.t-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt}sparks=sparks.filter(p=>p.t>0);flash=Math.max(0,flash-dt);if(spin>0){spin=Math.max(0,spin-dt);if(!spin){if(reels.every(n=>n===reels[0])){stock+=100;wins++;flash=2;tone(1050,.5);msg('잭팟! 구슬 100개를 획득했습니다.')}else msg('릴 추첨 완료 · 다음 입상을 노려보세요.');if(queue){queue--;startSpin()}status()}}}
let last=performance.now(),acc=0;function frame(ms){acc+=Math.min(.05,(ms-last)/1000);last=ms;while(acc>=1/120){step(1/120);acc-=1/120}draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
$('power').oninput=e=>{let v=e.target.value,p=(v-15)/85*100;$('pct').textContent=v;e.target.style.background='linear-gradient(to right,#ba8f54 '+p+'%,#424139 '+p+'%)'};
$('fire').onpointerdown=e=>{if(e.button!==0)return;e.target.setPointerCapture(e.pointerId);held=true;fire()};$('fire').onclick=e=>{if(!e.detail)fire()};for(let evt of ['pointerup','pointercancel','blur'])window.addEventListener(evt,()=>held=false);
